package modeselect_test

import (
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"testing"

	"github.com/SukramJ/go-fabric/cluster/modeselect"
	"github.com/SukramJ/go-fabric/cluster/spec"
	msdef "github.com/SukramJ/go-fabric/cluster/spec/modeselect"
	"github.com/SukramJ/go-fabric/tlv"
)

// modeselect-wire-fixtures.json holds matter.js's own encodings of
// SupportedModes (TlvOfModel of the attribute element), regenerated by
// notes/parity/matter/generate-modeselect-fixtures.ts.
//
//go:embed testdata/modeselect-wire-fixtures.json
var modeSelectWireFixturesJSON []byte

// TestSupportedModesMatchMatterJS: the value the server reads for
// SupportedModes encodes, through the generated codec, to the bytes
// matter.js writes for the same in-bounds list — smallest-width integers
// included (a 0 MfgCode is one byte, 0xFFF1 two), where the retired
// hand-written encoder wrote every SemanticTag field as a fixed uint16.
func TestSupportedModesMatchMatterJS(t *testing.T) {
	t.Parallel()
	var fixtures []struct {
		Label   string `json:"label"`
		Cluster uint32 `json:"cluster"`
		Element string `json:"element"`
		Fixture []struct {
			Label        string `json:"label"`
			Mode         uint8  `json:"mode"`
			SemanticTags []struct {
				MfgCode uint16 `json:"mfgCode"`
				Value   uint16 `json:"value"`
			} `json:"semanticTags"`
		} `json:"fixture"`
		BytesHex string `json:"bytesHex"`
	}
	if err := json.Unmarshal(modeSelectWireFixturesJSON, &fixtures); err != nil || len(fixtures) == 0 {
		t.Fatalf("fixtures: %v (%d)", err, len(fixtures))
	}
	for _, f := range fixtures {
		t.Run(f.Label, func(t *testing.T) {
			t.Parallel()
			if f.Cluster != msdef.ClusterID || f.Element != "SupportedModes" {
				t.Fatalf("fixture for 0x%04X %s", f.Cluster, f.Element)
			}
			src := &fakeSource{modes: []modeselect.ModeOptionStruct{}}
			for _, m := range f.Fixture {
				opt := modeselect.ModeOptionStruct{Label: m.Label, Mode: m.Mode, SemanticTags: []modeselect.SemanticTagStruct{}}
				for _, st := range m.SemanticTags {
					opt.SemanticTags = append(opt.SemanticTags, modeselect.SemanticTagStruct{MfgCode: st.MfgCode, Value: st.Value})
				}
				src.modes = append(src.modes, opt)
			}
			srv := modeselect.NewServer(modeselect.Config{Source: src})
			v, ok := srv.MatterRead(modeselect.AttrSupportedModes)
			if !ok {
				t.Fatal("SupportedModes not read")
			}
			enc, isEnc := v.(spec.Encodable)
			if !isEnc {
				t.Fatalf("SupportedModes is %T, not a spec.Encodable", v)
			}
			e := tlv.NewEncoder()
			enc.EncodeTLV(e, tlv.AnonymousTag())
			got, err := e.Bytes()
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(got) != f.BytesHex {
				t.Errorf("bytes %x, matter.js %s", got, f.BytesHex)
			}
		})
	}
}
